# 2. 核心大模型调用与解析函数
# ==========================================
total_tokens = 0
prompt_tokens = 0
completion_tokens = 0

def generate_summary_with_retry(prompt: str, max_retries: int = 3) -> str:
    """调用大模型并带自动重试机制（防止网络抖动或并发超限）"""
    global total_tokens, prompt_tokens, completion_tokens
    for attempt in range(max_retries):
        try:
            response = client.chat.completions.create(
                model=MODEL_NAME,
                messages=[
                    {"role": "system", "content": "You are a highly capable knowledge graph summarizer."},
                    {"role": "user", "content": prompt}
                ],
                temperature=0.3, # 较低的 temperature 保证事实准确性
            )
            if hasattr(response, 'usage') and response.usage:
                prompt_tokens += response.usage.prompt_tokens
                completion_tokens += response.usage.completion_tokens
                total_tokens += response.usage.total_tokens
            return response.choices[0].message.content.strip()
        except Exception as e:
            print(f"[API 错误] 尝试 {attempt + 1}/{max_retries} 失败: {e}")
            if attempt < max_retries - 1:
                time.sleep(2) # 失败后休眠 2 秒
    return ""

def process_subgraph_summary(data_item: dict) -> dict:
    """处理单个数据字典，生成 summary 并注入回字典"""
    
    triples = data_item.get("triples", [])
    if not triples:
        data_item["summary"] = ""
        return data_item

    # 为了让大模型更好理解，将 triples 格式化为易读的 JSON 字符串
    triples_str = json.dumps(triples, ensure_ascii=False, indent=2)

    # 构造 Prompt
    summary_prompt = (
        "You are given several text snippets, which represent real-world facts. "
        "Your task is to generate one summary to rephrase all information while exploring potential relationships across the snippets. Specifically:\n"
        "-Be accurate and complete, preserving ALL factual details like color or properties; and numeric details like quantity or coordinate.\n"
        "-rewrite the original context in a completely different way, tone, writing style, and logic to summarize the original context.\n"
        "-Some rewriting techniques can be used, including reordering, exchanging active and passive sentences, or synonym replacement.\n"
        "-If only one text snippet, simply do the summarization and rephrase.\n"
        "-If multiple text snippets are provided, focus on the relations between different text sentences, like multi-entity connections (e.g., triangle relations).\n"
        "The text snippets are provided below:\n"
        f"{triples_str}\n"
        "Your response MUST follow EXACTLY this format with no additional text:\n"
        "SUMMARY_START\n"
        "[Your summary text here, no line breaks within the summary]\n"
        "SUMMARY_END"
    )

    # 调用 API
    raw_response = generate_summary_with_retry(summary_prompt)

    # 先移除<think>...</think>思考标签
    raw_response = re.sub(r'<think>.*?</think>', '', raw_response, flags=re.DOTALL).strip()

    # 解析输出：根据固定格式提取
    match = re.search(r'SUMMARY_START\s*(.*?)\s*SUMMARY_END', raw_response, re.IGNORECASE | re.DOTALL)
    if match:
        clean_summary = match.group(1).strip()
    else:
        # 兜底：取第一行非空内容
        lines = raw_response.split('\n')
        for line in lines:
            line = line.strip()
            if line:
                clean_summary = line
                break
    
    return data_item

